        # Arrange
        mock_server = MagicMock()
        mock_smtp.return_value = mock_server
        recipient = 'validrecipient@example.com'  # TODO: Change to a valid email address
        content = 'This is a test email.'

        # Act
        sendEmail(recipient, content)

        # Assert
        mock_server.sendmail.assert_called_once_with('maskmanmotivation@gmail.com', recipient, content)
        mock_server.close.assert_called_once()

